import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] tri = new long[(int) m];
        for (int i = 0; i < tri.length; i++) tri[i] = Long.parseLong(next());

        int rowsCount = (int) n;
        int start = (rowsCount - 1) * rowsCount / 2;
        long[] row = new long[rowsCount];
        for (int j = 0; j < rowsCount; j++) row[j] = tri[start + j];
        for (int i = rowsCount - 2; i >= 0; i--) {
            int base = i * (i + 1) / 2;
            for (int j = 0; j <= i; j++) {
                row[j] = tri[base + j] + Math.min(row[j], row[j + 1]);
            }
        }
        System.out.println(row[0]);
    }
}
